<template>
  <div class="admin-workspace">
    <aside class="admin-rail">
      <button class="admin-back" type="button" @click="emit('back-home')"><span>←</span><strong>学习控制台</strong></button>
      <section class="admin-brand"><small>SYSTEM / ADMIN DESK</small><h1>管理员控制台</h1><p>查看系统运行概览、用户账号与内容活跃度。</p></section>
      <section class="admin-status" :class="{ ready: isAdmin }"><span>{{ isAdmin ? 'ADMIN ACCESS' : 'RESTRICTED' }}</span><strong>{{ isAdmin ? '系统管理权限已验证' : '需要管理员权限' }}</strong><small>{{ isAdmin ? '账号、资料、题库和社区动态' : '请使用管理员账号登录' }}</small></section>
      <section class="admin-rail-note"><span>NOTE 01</span><p>账号停用会立即阻断该用户的后续 API 访问。</p></section>
    </aside>

    <main class="admin-main">
      <header class="admin-topbar"><div><span>OPERATIONS OVERVIEW</span><h2>系统运行与学习社区</h2></div><button type="button" :disabled="loading" @click="loadData"><span>↻</span>{{ loading ? '同步中...' : '刷新数据' }}</button></header>
      <section v-if="!isAdmin" class="admin-restricted"><span>ACCESS CONTROL</span><h3>这里是管理员专属的系统控制台。</h3><p>当前账号没有 ADMIN 角色，导航入口和后端接口都会保持受限。</p><button type="button" @click="emit('back-home')">返回学习控制台</button></section>

      <template v-else>
        <p v-if="error" class="admin-error">{{ error }}</p>
        <section class="admin-stats" aria-label="系统统计"><article v-for="item in statCards" :key="item.label" :class="['admin-stat', item.tone]"><span>{{ item.code }}</span><strong>{{ item.value }}</strong><small>{{ item.label }}</small><i></i></article></section>
        <section class="admin-content-grid">
          <section class="admin-panel admin-activity-panel"><header><div><span>COMMUNITY PULSE</span><h3>近期内容动态</h3></div><em>{{ overview.forumThreadCount || 0 }} POSTS</em></header><div v-if="!overview.recentActivities?.length" class="admin-empty">暂无社区动态，发布讨论后会显示在这里。</div><ol v-else class="admin-activity-list"><li v-for="(activity, index) in overview.recentActivities" :key="`${activity.title}-${index}`"><span>{{ String(index + 1).padStart(2, '0') }}</span><div><strong>{{ activity.title }}</strong><p>{{ activity.detail }}</p></div><time>{{ formatTime(activity.occurredAt) }}</time></li></ol></section>
          <section class="admin-panel admin-system-note"><span>SYSTEM NOTE</span><h3>平稳运行中</h3><p>从这里快速掌握学习内容的沉淀、用户活跃情况与社区更新。</p><div><span><b>{{ overview.activeUserCount || 0 }}</b> 个正常账号</span><span><b>{{ overview.studyPlanCount || 0 }}</b> 条学习计划</span></div></section>
        </section>
        <section class="admin-panel admin-users-panel"><header><div><span>ACCOUNT DESK</span><h3>最近注册用户</h3></div><em>{{ users.length }} ACCOUNTS</em></header><div class="admin-table-wrap"><table><thead><tr><th>用户</th><th>角色</th><th>状态</th><th>注册时间</th><th>操作</th></tr></thead><tbody><tr v-if="!users.length"><td colspan="5" class="admin-empty">暂无可展示的用户数据。</td></tr><tr v-for="user in users" :key="user.id"><td><div class="admin-user-cell"><span>{{ initials(user) }}</span><div><strong>{{ user.nickname || user.username }}</strong><small>{{ user.email || `@${user.username}` }}</small></div></div></td><td><span class="admin-role">{{ (user.roles || ['USER']).join(' · ') }}</span></td><td><span :class="['admin-user-status', user.status === 1 ? 'active' : 'disabled']">{{ user.status === 1 ? '正常' : '已停用' }}</span></td><td>{{ formatTime(user.createdAt) }}</td><td><button class="admin-toggle" type="button" :disabled="changingUserId === user.id" @click="toggleUserStatus(user)">{{ changingUserId === user.id ? '处理中' : user.status === 1 ? '停用' : '恢复' }}</button></td></tr></tbody></table></div></section>
      </template>
    </main>
  </div>
</template>

<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { getAdminOverview, listAdminUsers, updateAdminUserStatus } from '../../api'

const props = defineProps({ isAdmin: Boolean })
const emit = defineEmits(['back-home'])
const loading = ref(false)
const changingUserId = ref(null)
const error = ref('')
const overview = ref({})
const users = ref([])
const statCards = computed(() => [
  { code: 'US', label: '系统用户', value: overview.value.userCount ?? '-', tone: 'blue' },
  { code: 'RS', label: '学习资料', value: overview.value.resourceCount ?? '-', tone: 'cyan' },
  { code: 'QB', label: '有效题目', value: overview.value.questionCount ?? '-', tone: 'violet' },
  { code: 'SH', label: '共享资源', value: overview.value.sharedResourceCount ?? '-', tone: 'pink' },
])
function formatTime(value) { if (!value) return '—'; const date = new Date(value); return Number.isNaN(date.getTime()) ? String(value).replace('T', ' ').slice(0, 16) : new Intl.DateTimeFormat('zh-CN', { month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }).format(date) }
function initials(user) { return String(user.nickname || user.username || 'U').trim().slice(0, 1).toUpperCase() }
async function loadData() { if (!props.isAdmin) return; loading.value = true; error.value = ''; try { const [overviewResponse, usersResponse] = await Promise.all([getAdminOverview(), listAdminUsers()]); overview.value = overviewResponse.data?.data || {}; users.value = usersResponse.data?.data || [] } catch (requestError) { error.value = requestError.response?.data?.message || '控制台数据暂时无法加载' } finally { loading.value = false } }
async function toggleUserStatus(user) { changingUserId.value = user.id; error.value = ''; try { const response = await updateAdminUserStatus(user.id, user.status === 1 ? 0 : 1); const saved = response.data?.data; const index = users.value.findIndex((item) => item.id === user.id); if (saved && index >= 0) users.value.splice(index, 1, saved); if (saved?.status === 0) overview.value.activeUserCount = Math.max(0, (overview.value.activeUserCount || 0) - 1); if (saved?.status === 1) overview.value.activeUserCount = (overview.value.activeUserCount || 0) + 1 } catch (requestError) { error.value = requestError.response?.data?.message || '账号状态更新失败' } finally { changingUserId.value = null } }
watch(() => props.isAdmin, (isAdmin) => { if (isAdmin) loadData() })
onMounted(loadData)
</script>

<style scoped>
