d var(--admin-line)}.admin-topbar h2{margin:4px 0 0;font-size:clamp(24px,2.4vw,34px)}.admin-topbar button{display:flex;align-items:center;gap:7px;min-height:38px;padding:0 12px}.admin-topbar button span{color:var(--admin-blue);font-size:20px}.admin-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.admin-stat{position:relative;display:grid;gap:6px;min-height:142px;padding:17px;overflow:hidden;border:1px solid var(--admin-line);background:rgba(255,255,255,.76)}.admin-stat>span{color:var(--admin-muted);font-size:11px;font-weight:900;letter-spacing:.08em}.admin-stat strong{font-size:34px;line-height:1}.admin-stat small{color:var(--admin-muted);font-size:13px;font-weight:900}.admin-stat i{position:absolute;right:-20px;bottom:-27px;width:92px;height:92px;border:1px solid currentColor;border-radius:48% 52% 54% 46%;opacity:.16;transform:rotate(26deg)}.admin-stat.blue{color:#386df5}.admin-stat.cyan{color:#2d9ec8}.admin-stat.violet{color:#8c6ce0}.admin-stat.pink{color:#d96eaa}.admin-content-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(230px,.75fr);gap:14px}.admin-panel,.admin-restricted{border:1px solid var(--admin-line);background:rgba(255,255,255,.7);box-shadow:0 14px 34px rgba(99,126,194,.08)}.admin-panel>header{padding:15px 17px;border-bottom:1px solid var(--admin-line)}.admin-panel h3,.admin-restricted h3{margin:4px 0 0;font-size:18px}.admin-panel header em{color:var(--admin-muted);font-size:10px;font-style:normal;font-weight:900;letter-spacing:.06em}.admin-activity-list{display:grid;gap:0;margin:0;padding:0;list-style:none}.admin-activity-list li{display:grid;grid-template-columns:30px minmax(0,1fr) auto;align-items:center;gap:10px;min-height:64px;padding:9px 17px;border-bottom:1px solid rgba(73,116,221,.1)}.admin-activity-list li:last-child{border-bottom:0}.admin-activity-list li>span{color:#bca8ff;font-size:12px;font-weight:900}.admin-activity-list strong{font-size:13px}.admin-activity-list p{margin:3px 0 0;overflow:hidden;color:var(--admin-muted);font-size:11px;font-weight:800;text-overflow:ellipsis;white-space:nowrap}.admin-activity-list time{color:var(--admin-muted);font-size:11px;font-weight:800}.admin-system-note{display:grid;align-content:start;gap:11px;padding:20px;background:linear-gradient(145deg,rgba(241,247,255,.9),rgba(255,245,251,.88))}.admin-system-note h3{margin:0;font-size:24px}.admin-system-note p{margin:0;color:var(--admin-muted);font-size:13px;font-weight:800;line-height:1.75}.admin-system-note>div{display:grid;gap:9px;margin-top:7px}.admin-system-note>div span{padding-top:9px;border-top:1px solid var(--admin-line);color:var(--admin-muted);font-size:12px;font-weight:800}.admin-system-note b{color:var(--admin-blue);font-size:18px}.admin-users-panel{margin-top:14px}.admin-table-wrap{overflow-x:auto}.admin-users-panel table{width:100%;border-collapse:collapse;min-width:640px}.admin-users-panel th{padding:11px 17px;color:var(--admin-muted);text-align:left;font-size:11px}.admin-users-panel td{padding:10px 17px;border-top:1px solid rgba(73,116,221,.1);color:var(--admin-muted);font-size:12px;font-weight:800}.admin-user-cell{display:flex;align-items:center;gap:10px}.admin-user-cell>span{display:grid;width:30px;height:30px;place-items:center;border:1px solid var(--admin-line);border-radius:50%;color:var(--admin-blue);background:linear-gradient(135deg,#ecf3ff,#fff2fa);font-weight:900}.admin-user-cell div{display:grid;gap:2px}.admin-user-cell strong{color:var(--admin-ink);font-size:13px}.admin-user-cell small{font-size:11px}.admin-role,.admin-user-status{display:inline-block;padding:4px 7px;border:1px solid var(--admin-line);font-size:10px}.admin-user-status.active{color:#2c998c;background:rgba(224,250,245,.7)}.admin-user-status.disabled{color:#bd6680;background:rgba(255,236,242,.78)}.admin-toggle{min-height:28px;padding:0 9px;color:var(--admin-blue);font-size:11px}.admin-toggle:disabled{opacity:.6;cursor:wait}.admin-error{margin:16px 0 0;padding:9px 12px;border:1px solid rgba(212,91,119,.28);color:#bd5570;background:rgba(255,239,244,.72);font-size:12px;font-weight:900}.admin-empty{padding:24px 17px;color:var(--admin-muted);font-size:13px;font-weight:800;text-align:center}.admin-restricted{max-width:650px;display:grid;gap:12px;margin:44px auto;padding:30px;text-align:center}.admin-restricted h3{font-size:24px}.admin-restricted p{margin:0;color:var(--admin-muted);font-weight:800;line-height:1.8}.admin-restricted button{justify-self:center;padding:10px 14px;color:var(--admin-blue)}@media(max-width:980px){.admin-workspace{grid-template-columns:1fr}.admin-rail{min-height:auto;grid-template-columns:auto 1fr auto;align-items:center;gap:14px;border-right:0;border-bottom:1px solid var(--admin-line)}.admin-brand{display:none}.admin-rail-note{display:none}.admin-main{padding:22px}.admin-stats{grid-template-columns:repeat(2,1fr)}.admin-content-grid{grid-template-columns:1fr}}@media(max-width:600px){.admin-rail{grid-template-columns:1fr}.admin-status{display:none}.admin-main{padding:16px}.admin-topbar{align-items:flex-start}.admin-topbar button{white-space:nowrap}.admin-stats{grid-template-columns:1fr 1fr}.admin-stat{min-height:112px}.admin-stat strong{font-size:27px}.admin-activity-list li{grid-template-columns:24px minmax(0,1fr)}.admin-activity-list time{display:none}}
</style>
